'use strict';

/**
* LAPACK routine to return a vector of `n` random real numbers from a uniform or normal distribution.
*
* @module @stdlib/lapack/base/dlarnv
*
* @example
* var Int32Array = require( '@stdlib/array/int32' );
* var Float64Array = require( '@stdlib/array/float64' );
* var dlarnv = require( '@stdlib/lapack/base/dlarnv' );
*
* var iseed = new Int32Array( [ 0, 1, 2, 3 ] );
* var x = new Float64Array( 5 );
*
* dlarnv( 1, iseed, 5, x );
* // x => <Float64Array>
*
* @example
* var Int32Array = require( '@stdlib/array/int32' );
* var Float64Array = require( '@stdlib/array/float64' );
* var dlarnv = require( '@stdlib/lapack/base/dlarnv' );
*
* var iseed = new Int32Array( [ 0, 1, 2, 3 ] );
* var x = new Float64Array( 5 );
*
* dlarnv.ndarray( 1, iseed, 1, 0, 5, x, 1, 0 );
* // x => <Float64Array>
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dlarnv;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dlarnv = main;
} else {
	dlarnv = tmp;
}


// EXPORTS //

module.exports = dlarnv;

// exports: { "ndarray": "dlarnv.ndarray" }
